SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY X.ATCH_FILE_ID DESC) AS RNUM, X.* FROM ( SELECT A.ATCH_FILE_ID, SUBSTRING(A.FILE_STRE_COURS FROM POSITION('/' IN A.FILE_STRE_COURS)) AS FILE_STRE_COURS, A.STRE_FILE_NM, A.FILE_EXTSN, A.CON_SEQ, A.FILE_ORDER, A.FILE_THUMNAIL, A.ORIGNL_FILE_NM, CASE WHEN LOWER(A.FILE_EXTSN) IN ('mp4', 'avi', 'mpeg') THEN 'MEDIA' WHEN LOWER(A.FILE_EXTSN) IN ('jpg', 'jpeg', 'gif', 'png', 'bmp') THEN 'IMAGE' WHEN LOWER(A.FILE_EXTSN) IN ('mp3', 'wav', 'mid') THEN 'MUSIC' END AS mediaType, A.PLAY_TIME, A.FILE_WIDTH, A.FILE_HEIGHT, A.UseYN, A.FILE_GUBUN FROM LETTNFILEDETAIL A WHERE 1=1
AND A.GROUP_ID IN ( WITH RECURSIVE cte AS ( SELECT GROUP_ID, PARENT_GROUP_ID FROM LETTNAUTHORGROUPINFO WHERE GROUP_ID = (SELECT PART_ID FROM TB_MANAGERINFO WHERE MANAGER_ID = #{mberId}) UNION ALL SELECT g.GROUP_ID, g.PARENT_GROUP_ID FROM LETTNAUTHORGROUPINFO g JOIN cte ON g.PARENT_GROUP_ID = cte.GROUP_ID ) SELECT GROUP_ID FROM cte )
AND A.CENTER_ID = (SELECT CENTER_ID FROM TB_MANAGERINFO WHERE MANAGER_ID = #{mberId})
AND STRE_FILE_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND ORIGNL_FILE_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.FILE_GUBUN = #{fileGubun}
) X WHERE 1=1
AND X.mediaType = #{mediaType}
AND X.mediaType != #{notConType}
AND X.FILE_THUMNAIL = 'no_image.png'
AND (X.FILE_THUMNAIL != 'no_image.png' OR X.FILE_THUMNAIL IS NULL)
) TA WHERE RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY X.ATCH_FILE_ID DESC) AS RNUM, X.* FROM ( SELECT A.ATCH_FILE_ID, SUBSTRING(A.FILE_STRE_COURS FROM POSITION('/' IN A.FILE_STRE_COURS)) AS FILE_STRE_COURS, A.STRE_FILE_NM, A.FILE_EXTSN, A.CON_SEQ, A.FILE_ORDER, A.FILE_THUMNAIL, A.ORIGNL_FILE_NM, A.FILE_GUBUN, CASE WHEN LOWER(A.FILE_EXTSN) IN ('mp4', 'avi', 'mpeg') THEN 'MEDIA' WHEN LOWER(A.FILE_EXTSN) IN ('jpg', 'jpeg', 'gif', 'png', 'bmp') THEN 'IMAGE' WHEN LOWER(A.FILE_EXTSN) IN ('mp3', 'wav', 'mid') THEN 'MUSIC' END AS mediaType, A.PLAY_TIME, A.FILE_WIDTH, A.FILE_HEIGHT, A.UseYN FROM LETTNFILEDETAIL A WHERE 1=1
AND STRE_FILE_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND ORIGNL_FILE_NM LIKE CONCAT('%', #{searchKeyword}, '%')
) X WHERE X.mediaType = 'MUSIC' AND X.FILE_GUBUN = 'fileGubun02' ) TA WHERE RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY X.ATCH_FILE_ID DESC) AS RNUM, COUNT(*) OVER() AS totalRecodCount, X.* FROM ( SELECT A.ATCH_FILE_ID, SUBSTRING(A.FILE_STRE_COURS FROM POSITION('/' IN A.FILE_STRE_COURS)) AS FILE_STRE_COURS, A.STRE_FILE_NM, A.FILE_EXTSN, A.CON_SEQ, A.FILE_ORDER, A.FILE_THUMNAIL, A.ORIGNL_FILE_NM, A.FILE_GUBUN, CASE WHEN A.FILE_EXTSN IN ('mp4', 'avi', 'mpeg') THEN 'MEDIA' WHEN A.FILE_EXTSN IN ('jpg', 'jpeg', 'gif', 'png', 'bmp') THEN 'IMAGE' WHEN A.FILE_EXTSN IN ('mp3', 'wav', 'mid') THEN 'MUSIC' END AS mediaType, A.PLAY_TIME, A.FILE_WIDTH, A.FILE_HEIGHT, A.UseYN FROM LETTNFILEDETAIL A WHERE 1=1
AND STRE_FILE_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND ORIGNL_FILE_NM LIKE CONCAT('%', #{searchKeyword}, '%')
) X WHERE X.mediaType = 'MUSIC' AND X.FILE_GUBUN = 'fileGubun02' ) TA WHERE RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

SELECT COALESCE(COUNT(*), 0) FROM ( SELECT CASE WHEN LOWER(FILE_EXTSN) IN ('mp4', 'avi', 'mpeg') THEN 'MEDIA' WHEN LOWER(FILE_EXTSN) IN ('jpg', 'jpeg', 'gif', 'png', 'bmp') THEN 'IMAGE' WHEN LOWER(FILE_EXTSN) IN ('mp3', 'wav', 'mid') THEN 'MUSIC' END AS mediaType, ATCH_FILE_ID, FILE_GUBUN FROM LETTNFILEDETAIL WHERE 1=1
AND GROUP_ID IN ( WITH RECURSIVE cte AS ( SELECT GROUP_ID, PARENT_GROUP_ID FROM LETTNAUTHORGROUPINFO WHERE GROUP_ID = (SELECT PART_ID FROM TB_MANAGERINFO WHERE MANAGER_ID = #{mberId}) UNION ALL SELECT g.GROUP_ID, g.PARENT_GROUP_ID FROM LETTNAUTHORGROUPINFO g JOIN cte ON g.PARENT_GROUP_ID = cte.GROUP_ID ) SELECT GROUP_ID FROM cte )
AND CENTER_ID = (SELECT CENTER_ID FROM TB_MANAGERINFO WHERE MANAGER_ID = #{mberId})
AND STRE_FILE_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND ORIGNL_FILE_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND FILE_GUBUN = #{fileGubun}
AND FILE_THUMNAIL = 'no_image.png'
AND (FILE_THUMNAIL != 'no_image.png' OR FILE_THUMNAIL IS NULL)
) X WHERE 1=1
AND X.mediaType = #{mediaType}
AND X.mediaType != #{notConType}

